"use client";
/* Cube, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Cube(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("cube"); }, []);
  return React.createElement("piix-pal", { "pal": "cube", ...piixAttrs(props) });
}

export default Cube;
